\u0036\u0058\u0025\u0071\u0044\u0066\u0058\u0053\u0057\u0048\u0023\u0060\u005e\u0037\u003b\u0034\u0045\u007e\u0054\u004a\u004a\u004f\u0054\u005f\u0066\u0041\u0079\u0061\u0036\u0037\u002c\u007c\u004f\u0023\u0058\u003e\u002b\u0045\u0054\u0028\u0064\u006a\u0059\u0032\u006e\u006c\u0040\u0043\u005b\u0043\u0046\u0036\u0056\u0048\u004b\u0070\u004c\u0062\u004f\u0025\u0054\u003c\u0039\u0049\u005a\u006e\u0046\u004b\u0073\u0048\u0035\u0043\u0076\u0054\u006d\u0046\u005e\u0037\u0037\u002e\u0072\u003f\u0074\u0046\u006f\u0079\u005d\u0041\u0054\u0026\u0037\u0066\u0048\u006f\u0045\u0074\u003a\u002e\u007b\u004f\u0033\u0055\u0033\u0063\u0047\u006a\u0037\u0059\u002f\u003d\u0049\u0025\u0039\u006f\u0028\u0054\u002c\u0037\u003d\u002e\u003d\u004d\u0066\u004b\u0050\u002b\u0039\u002e\u002f\u0029\u0044\u0032\u0048\u004b\u0077\u002e\u006c\u0028\u0076\u0054\u003a\u006d\u0057\u002f\u004a\u0074\u0056\u004c\u0057\u0075\u0025\u0058\u0074\u0042\u005e\u0035\u006d\u0061\u0033\u0044\u007a\u0029\u006e\u0037\u005a\u003b\u0044\u002b\u0071\u0030\u0057\u0075\u007e\u0028\u0040\u0076\u0036\u0037\u006f\u0043\u0079\u0043\u0038\u0062\u004e\u0035\u006a\u0061\u0052\u0022\u0048\u0036\u006d\u0058\u0069\u004a\u006c\u0035\u005d\u0049\u0064\u004d\u0055\u0042\u0042\u007b\u005f\u0026\u0075\u0062\u0046\u004c\u0076\u002c\u0042\u0028\u007c\u0036\u006a\u0025\u007b\u0043\u0043\u005f\u003e\u0042\u002a\u002c\u0038\u006e\u007d\u007b\u002a\u0076\u0047\u0047\u0030\u0031\u0054\u005a\u003e\u0055\u003d\u0059\u004d\u007b\u004c\u0051\u006c\u006e\u0032\u005a\u007a\u0030\u002b\u006a\u0078\u0065\u0078\u0076\u0022\u006c\u0047\u0058\u0074\u003b\u0066\u0025\u0044\u0055\u0043\u004d\u007b\u0039\u0042\u0037\u0047\u003b\u0030\u003b\u0040\u0060\u006e\u0048\u005e\u0063\u0044\u0030\u0074\u002b\u0076\u0033\u004f\u004f\u007d\u007e\u002c\u0042\u0050\u0030\u004e\u0041\u007d\u007b\u005f\u0057\u004c\u0070\u0069\u005a\u0056\u007c\u006c\u006b\u0051\u006d\u005a\u0075\u0076\u0038\u002e\u0029\u0077\u007b\u003c\u0062\u006c\u0022\u0061\u0063\u0079\u005b\u0052\u0057\u007e\u007b\u0077\u0023\u0035\u0065\u0061\u0065\u003b\u0024\u0076\u0038\u0065\u0076\u004d\u006b\u007d\u006a\u005a\u0039\u0036\u006f\u0038\u007e\u0029\u006d\u005a\u0074\u006e\u003f\u0069\u004e\u0038\u0023\u0024\u0036\u006b\u0050\u0044\u0075\u0075\u002b\u0077\u004c\u0057\u0036\u003e\u007c\u007d\u007c\u0037\u002e\u0052\u0073\u002a\u0023\u0033\u0057\u005a\u0060\u002a\u003d\u0052\u0028\u004a\u0028\u005f\u0076\u0041\u0025\u0079\u006e\u002b\u0044\u002b\u003e\u0056\u0046\u002a\u0079\u0051\u0060\u0040\u0052\u003b\u0078\u0072\u0044\u006f\u0021\u0033\u002f\u0054\u005f\u005a\u0057\u0039\u0072\u0046\u0052\u005d\u004c\u0060\u0049\u0073\u005d\u0062\u0024\u0021\u006c\u0053\u0058\u0057\u0076\u0035\u004a\u0053\u004c\u0055\u006e\u0046\u0070\u0077\u0077\u0056\u002b\u003f\u0032\u0041\u0053\u006a\u003d\u003f\u0075\u0040\u004d\u0048\u006b\u006b\u0023\u0036\u007a\u005d\u0031\u0060\u0058\u0052\u0072\u0047\u006d\u007c\u0023\u0022\u0032\u0051\u0071\u004e\u006d\u005d\u005f\u0022\u007a\u0051\u003c\u0039\u0024\u0067\u0077\u0040\u007b\u0076\u0023\u0078\u0057\u002b\u003a\u0036\u0065\u0065\u0029\u0060\u0071\u0053\u003b\u0047\u0023\u007d\u006f\u006d\u0073\u004e\u0070\u0031\u002b\u0078\u003d\u0053\u004b\u0053\u0033\u0029\u0043\u0039\u0044\u0049\u0044\u0057\u0062\u0040\u005e\u004d\u007d\u0056\u003d\u0052\u0047\u0060\u0055\u0076\u003c\u0038\u0052\u002b\u0076\u0069\u0030\u004e\u0048\u006d\u0065\u003d\u0074\u0024\u0063\u003e\u005d\u0047\u0044\u0039\u002a\u0065\u0024\u0029\u0024\u0053\u0055\u0037\u005d\u0029\u0074\u007e\u006b\u0053\u0033\u005f\u0022\u0042\u0029\u002e\u007e\u0048\u006d\u0065\u0060\u0026\u0023\u0052\u0036\u0053\u002b\u005b\u0066\u003c\u0039\u0022\u0031\u002b\u004c\u0034\u0030\u003f\u0076\u0048\u0039\u0030\u0035\u005a\u0029\u006b\u002c\u0069\u003f\u007a\u006c\u0023\u0051\u004b\u004e\u0052\u005e\u003a\u005b\u006d\u0033\u003b\u0050\u004a\u0057\u0032\u0051\u0040\u002b\u004d\u0069\u002f\u0024\u006a\u0070\u0061\u0077\u006c\u0073\u004a\u0057\u0047\u0034\u002c\u0054\u0034\u004a\u0062\u004a\u0034\u002e\u0055\u0042\u006b\u0066\u0041\u0045\u004e\u0025\u0056\u0051\u003f\u005a\u0067\u0021\u0036\u0065\u0028\u0029\u0046\u005b\u0032\u003c\u0069\u0074\u0070\u0061\u007d\u0022\u005b\u0032\u003c\u0069\u0057\u0049\u005b\u0053\u0070\u0061\u0049\u0078\u0037\u0057\u0045\u0062\u0039\u006e\u003e\u0070\u0061\u005d\u0022\u0033\u003e\u0045\u006b\u0058\u0045\u004f\u0025\u003f\u0074\u0077\u0040\u0024\u0064\u005d\u0058\u007d\u0063\u0059\u0068\u0066\u004b\u0022\u0028\u0035\u0061\u005a\u006c\u0077\u003c\u004e\u0031\u0062\u0045\u0069\u0078\u003f\u0076\u007c\u0022\u0022\u007a\u0051\u0054\u0043\u0038\u006d\u0037\u0026\u007a\u002f\u002a\u004d\u005b\u0035\u002e\u0066\u0021\u006f\u0033\u0031\u0051\u002b\u002b\u0043\u0038\u0073\u0056\u003a\u006d\u0040\u003e\u0065\u007c\u0058\u007a\u0063\u002e\u0022\u0043\u0021\u005b\u006f\u006f\u0036\u0021\u005e\u002b\u0045\u0030\u0030\u0037\u0047\u006b\u0061\u003c\u005a\u0069\u002b\u007e\u005e\u0071\u0022\u007c\u005e\u0036\u002e\u0074\u006f\u007a\u0037\u007e\u0035\u0037\u005d\u0039\u0056\u006b\u0066\u004d\u0069\u0039\u0022\u007c\u0047\u006b\u0061\u003c\u0074\u007a\u0071\u006d\u0062\u0024\u0049\u0058\u0052\u0025\u003e\u0055\u0040\u003e\u006b\u0066\u006d\u0035\u0033\u007e\u0026\u0049\u0047\u006b\u0061\u003c\u0042\u002f\u0063\u007e\u0052\u0040\u0046\u0069\u0078\u0040\u0021\u0025\u007c\u0068\u0074\u0076\u007e\u002f\u0065\u0055\u0049\u0061\u006d\u0077\u005e\u006c\u006b\u0061\u003c\u002e\u006c\u0039\u0042\u006b\u0047\u0053\u0047\u006b\u0061\u003c\u0039\u0072\u0034\u0029\u0048\u005a\u0068\u0060\u0079\u0037\u0075\u0037\u003e\u006f\u0070\u003c\u004c\u0062\u006f\u005d\u0035\u0047\u006b\u0061\u003c\u0062\u0047\u0077\u007e\u0033\u003e\u0049\u0049\u004e\u0074\u0052\u0025\u0030\u0067\u005f\u003c\u003d\u002f\u004a\u0039\u002a\u0076\u0039\u0049\u005b\u0075\u003e\u0035\u0076\u007e\u0033\u0052\u0058\u002e\u003c\u0022\u0047\u006b\u0061\u003c\u0039\u0072\u007e\u0057\u006e\u0045\u0049\u0058\u0056\u006e\u0056\u0050\u0053\u004b\u006b\u0066\u0058\u007a\u0039\u0055\u0047\u006b\u0061\u003c\u007a\u0029\u005f\u0029\u002f\u005d\u002a\u002c\u0065\u003e\u0075\u0037\u004b\u006b\u002e\u003f\u002e\u006c\u0039\u0048\u006f\u002b\u007a\u0047\u006b\u0061\u003c\u0073\u0044\u0038\u0064\u0037\u0057\u006a\u002c\u0046\u0037\u0057\u004f\u0033\u0023\u0057\u007c\u0024\u002f\u0045\u004b\u0037\u003f\u007c\u0047\u006b\u0061\u003c\u0061\u0065\u0042\u005e\u004b\u005a\u0072\u0060\u0069\u0036\u005a\u0055\u0060\u0067\u0046\u0065\u0047\u006b\u0061\u003c\u0072\u0069\u005d\u0064\u0071\u005a\u004c\u006e\u0032\u0054\u0051\u0030\u0028\u0067\u003f\u002f\u0063\u0077\u0073\u006b\u0021\u003e\u0077\u0066\u0047\u006b\u0061\u003c\u007a\u0029\u0026\u006d\u0071\u005a\u0068\u0060\u0071\u003e\u0075\u0037\u0045\u003a\u0034\u0062\u002f\u0047\u006b\u0061\u003c\u0075\u0026\u0042\u005e\u0021\u005d\u003f\u0044\u004c\u0076\u0041\u007d\u006c\u0056\u0046\u006e\u0056\u004e\u003f\u006d\u0035\u0037\u007e\u003e\u0045\u0057\u007d\u0048\u0075\u006a\u0069\u006f\u007e\u0059\u0050\u0046\u0024\u0047\u006b\u0061\u003c\u007a\u0029\u0067\u007e\u0041\u0071\u004e\u0048\u002f\u007d\u006c\u002f\u0026\u0074\u0037\u007e\u0022\u002c\u005f\u0022\u0040\u0075\u0058\u007a\u0039\u0051\u0039\u0061\u004d\u003e\u0062\u0047\u006b\u0061\u003c\u002b\u006c\u0033\u002e\u0048\u0043\u0037\u005d\u0054\u0021\u0052\u0067\u0051\u0046\u0046\u003c\u002b\u0072\u0039\u0064\u0023\u0072\u0047\u006b\u0061\u003c\u007a\u0029\u006f\u007e\u002a\u0028\u0034\u0073\u0031\u007d\u0021\u0044\u0021\u0044\u004a\u0039\u0028\u003b\u0043\u0058\u002e\u0023\u005b\u0075\u004b\u0035\u0076\u007e\u006f\u0075\u0057\u0039\u0050\u0047\u006b\u0061\u003c\u005a\u0069\u0076\u007e\u0074\u003e\u0032\u0055\u002a\u002c\u0068\u0046\u0024\u003c\u0057\u0072\u0063\u007e\u0069\u0030\u0047\u006b\u0061\u003c\u006b\u007b\u0034\u0029\u0021\u005d\u0056\u0043\u0039\u0058\u0056\u0050\u0068\u006b\u0026\u0066\u0061\u0064\u0051\u0031\u0059\u0029\u006b\u0022\u0074\u002e\u006c\u0047\u005a\u0022\u0057\u0025\u007b\u0040\u0076\u0034\u0050\u0069\u0049\u0043\u0025\u0023\u0061\u005f\u006f\u0057\u0060\u0064\u0045\u003a\u0049\u007a\u0044\u007d\u002c\u0039\u0022\u0041\u0069\u0075\u0028\u0051\u0028\u002a\u0022\u007c\u0057\u0038\u004f\u0060\u0039\u0034\u0077\u0022\u0052\u0033\u003a\u0078\u0056\u0065\u0057\u0076\u0063\u0078\u005d\u0036\u0034\u0043\u0033\u0078\u0050\u005b\u0052\u006e\u0073\u0047\u0054\u002c\u007a\u006a\u004d\u0033\u0066\u0075\u003a\u0043\u004f\u007e\u002b\u0030\u0079\u004e\u003f\u002a\u0058\u004e\u002a\u0062\u0054\u0048\u0035\u0049\u0060\u003e\u0036\u0078\u0034\u007a\u0024\u003f\u003c\u006d\u0052\u005d\u003a\u004a\u005f\u0046\u0030\u0032\u005e\u006a\u003d\u003a\u0049\u0030\u0030\u0043\u0075\u0065\u0054\u0036\u0046\u0058\u007a\u0066\u0023\u0057\u006b\u006d\u004a\u0064\u0034\u0043\u0057\u0042\u0042\u0046\u0060\u006d\u0052\u004a\u003a\u0069\u0064\u005a\u002f\u0060\u002e\u005f\u0052\u0039\u0064\u0031\u002e\u0047\u0053\u0046\u0076\u0079\u003d\u006b\u007d\u003a\u0071\u003d\u0064\u006a\u0030\u0036\u005e\u005e\u0024\u003b\u0040\u0049\u006f\u0076\u0067\u004a\u0071\u0035\u0052\u003c\u0068\u005a\u0029\u0041\u0071\u006f\u0055\u0068\u0068\u0053\u006b\u0066\u004d\u007b\u003c\u0071\u0062\u003a\u003d\u004f\u0046\u003b\u0023\u006e\u0033\u0049\u0034\u0059\u005f\u0063\u006b\u0072\u006f\u0023\u0040\u003c\u0067\u0042\u0068\u004d\u0067\u0024\u0025\u0070\u0022\u0022\u0032\u004d\u0036\u0060\u0079\u003e\u005b\u0075\u004c\u003c\u004b\u0076\u003c\u0074\u0034\u0067\u0079\u0025\u002c\u0056\u0038\u0065\u0030\u0079\u003e\u0023\u0042\u0067\u003f\u002b\u004d\u005d\u0030\u0025\u002c\u0028\u0049\u0057\u002f\u0075\u0047\u0050\u0051\u0050\u0058\u003d\u003f\u0035\u0048\u007c\u0061\u0039\u0046\u003b\u002f\u004d\u007b\u0025\u0056\u0037\u0057\u004b\u006d\u004a\u0053\u003a\u004f\u007e\u0048\u005f\u002f\u0070\u0075\u0049\u0039\u002e\u0058\u006e\u0066\u0050\u0069\u0032\u0043\u0022\u0070\u002c\u0025\u005e\u0047\u004e\u0036\u0067\u0073\u0073\u0039\u0062\u0048\u0025\u006b\u0055\u0069\u0079\u0057\u003a\u0065\u005e\u0053\u0025\u0059\u0049\u0029\u0056\u007e\u0040\u0071\u002f\u0064\u0064\u0022\u002e\u0038\u006d\u0073\u0050\u0029\u004e\u0071\u0021\u0060\u0068\u003b\u005e\u0032\u006d\u004c\u0022\u0052\u003a\u007c\u0023\u007c\u0021\u0029\u0043\u005b\u007d\u0064\u0041\u0036\u0065\u0051\u0054\u0043\u0050\u0021\u0055\u0041\u0030\u003e\u0059\u0038\u0040\u0064\u0065\u0022\u0065\u0031\u007d\u0043\u0022\u0036\u0065\u003e\u006b\u0055\u0078\u0022\u0048\u0063\u0045\u0021\u006e\u0037\u003f\u0048\u0024\u0068\u0059\u004a\u005b\u005b\u0052\u005a\u0060\u0076\u005f\u0021\u0055\u0053\u0050\u0038\u006d\u005b\u0037\u0024\u0057\u003a\u0055\u0030\u005b\u003d\u0044\u007c\u0052\u0035\u003f\u002a\u0022\u003e\u002c\u0066\u0034\u0053\u0071\u0041\u004a\u0055\u0066\u0024\u006b\u0035\u007e\u0054\u0057\u005b\u005b\u0049\u0024\u0046\u0073\u0045\u0069\u0030\u005b\u005b\u0052\u005a\u0060\u0076\u0057\u0073\u0079\u0045\u0026\u0077\u0054\u005f\u006f\u006c\u0071\u004b\u004f\u0051\u004b\u0048\u0028\u003c\u0067\u0063\u004e\u003f\u003c\u0079\u0031\u0038\u0046\u007e\u0045\u0032\u004e\u0038\u0040\u005e\u004a\u0045\u0060\u004c\u0040\u0077\u0059\u0044\u002b\u0022\u0064\u0079\u0063\u0042\u007c\u0063\u0057\u0066\u002c\u0074\u0078\u005f\u0045\u0064\u0023\u005e\u0057\u005b\u0047\u006d\u0031\u007b\u004e\u0061\u0076\u0059\u0040\u006f\u003e\u0073\u0050\u005b\u0038\u0071\u0047\u005f\u0046\u0058\u006f\u0048\u0057\u0040\u0072\u007e\u0026\u0041\u0025\u005f\u003b\u0044\u0067\u003c\u004c\u0055\u006b\u0079\u006d\u003f\u0062\u0043\u0049\u0061\u0059\u003f\u0024\u004c\u0067\u002e\u0065\u005e\u0021\u007b\u0024\u0045\u0077\u0037\u002b\u0050\u0071\u005a\u007b\u0062\u0043\u0060\u003d\u006f\u0038\u0079\u0032\u0045\u0048\u007c\u007e\u0065\u007a\u0029\u0075\u0045\u0061\u0026\u0048\u0052\u006a\u0025\u006d\u0076\u007e\u0029\u003d\u0029\u007c\u0029\u0037\u0074\u0062\u0073\u005b\u004f\u004e\u0078\u0072\u0047\u0031\u0030\u005a\u006f\u0024\u0039\u0033\u002a\u003a\u0051\u0046\u006f\u003e\u0069\u0034\u0050\u005f\u007b\u006a\u006e\u0057\u0047\u0061\u003d\u0035\u007a\u0079\u0049\u0068\u007d\u004f\u0064\u0058\u0073\u0025\u0060\u002c\u003e\u005d\u007e\u0042\u003d\u002a\u0024\u004d\u0067\u0079\u0045\u0021\u0042\u006e\u004c\u002a\u004d\u0034\u0050\u007c\u0074\u0024\u004d\u0067\u0079\u007b\u003f\u0034\u0050\u0033\u0028\u0071\u0066\u0045\u003c\u0067\u003f\u0043\u0030\u0034\u0050\u0061\u0074\u0021\u0045\u005a\u0026\u006c\u006f\u0040\u003d\u0029\u003e\u003f\u0073\u0066\u0025\u0023\u005e\u0041\u0029\u0037\u003b\u0061\u003e\u0051\u0062\u0068\u0022\u0071\u0026\u0042\u0051\u004b\u004c\u005b\u0074\u0031\u0032\u0077\u0048\u0051\u005f\u0067\u004f\u0031\u0077\u007d\u0079\u0024\u002c\u004f\u005f\u0078\u005d\u0062\u0074\u0074\u0036\u0073\u0056\u0032\u0035\u0038\u003e\u0031\u0074\u0072\u003f\u004e\u0064\u0024\u0043\u002b\u004c\u0052\u003f\u003f\u0032\u0063\u006a\u0058\u0067\u0069\u0073\u0040\u0054\u0067\u0035\u006c\u003a\u006d\u003b\u0050\u0047\u002a\u0035\u007e\u005a\u0079\u0041\u0078\u004a\u0047\u0043\u0031\u007e\u0058\u0061\u0041\u0060\u005f\u0063\u0024\u0075\u0041\u003f\u0036\u0021\u0049\u0062\u004d\u0066\u007e\u0068\u003b\u0062\u0030\u005b\u005e\u0055\u0065\u0077\u0041\u007e\u006c\u003a\u006d\u003b\u0050\u0047\u002c\u0054\u0024\u002a\u0043\u0047\u0061\u006e\u0072\u0030\u005e\u0046\u0047\u0061\u006e\u0054\u0076\u0064\u005e\u003e\u0034\u005e\u0057\u0075\u003a\u0060\u0023\u0023\u005d\u0040\u0070\u0072\u0065\u0059\u0077\u0076\u007a\u0031\u0057\u0067\u0045\u0052\u005d\u0036\u0077\u007c\u007d\u0060\u003e\u0033\u006f\u006a\u0066\u0036\u0071\u007c\u0033\u002b\u0024\u0038\u003e\u0055\u003a\u0056\u005a\u002a\u0026\u0060\u004b\u0057\u0042\u006e\u0046\u004e\u002a\u0026\u0028\u0031\u004e\u0074\u0059\u0037\u006e\u0075\u0032\u0079\u004d\u0048\u0072\u0058\u002a\u0052\u0026\u0050\u0069\u006f\u0076\u0046\u0072\u0064\u003f\u0037\u007e\u0058\u0034\u003f\u0056\u005f\u007c\u004d\u0030\u0054\u0029\u0062\u0061\u004a\u003c\u007a\u0052\u003e\u004d\u0024\u0077\u005e\u0031\u0035\u006a\u0079\u0046\u0021\u0041\u002b\u0051\u0067\u006a\u0073\u0069\u003a\u006b\u0065\u003f\u0040\u0054\u004d\u0029\u0061\u0068\u0022\u006d\u0049\u0062\u0041\u007b\u0037\u004e\u0031\u005f\u004f\u0032\u003c\u0038\u0054\u0076\u005f\u0052\u0079\u0062\u0042\u0030\u0061\u0039\u006c\u002f\u0066\u0037\u0036\u006c\u005e\u005e\u005b\u0032\u0079\u004b\u0058\u0064\u006f\u003e\u002e\u005a\u0029\u0022\u0036\u0032\u002b\u0026\u0048\u006d\u006f\u0044\u007c\u0043\u003b\u0068\u0025\u0078\u006a\u002b\u0051\u0053\u006b\u0059\u0058\u0039\u0028\u004b\u006e\u0063\u0052\u006f\u006d\u0076\u0076\u0079\u0022\u0037\u0024\u0041\u0042\u005d\u004b\u004b\u0060\u003d\u002e\u006c\u0022\u0026\u004d\u004f\u005e\u003d\u0032\u0029\u0062\u004f\u0051\u0076\u006f\u002b\u004f\u002c\u0022\u0050\u0056\u002e\u0063\u002f\u0070\u0060\u0028\u0021\u0035\u0062\u0022\u007a\u005d\u0026\u0054\u005f\u0040\u0048\u0050\u006d\u0079\u0045\u0070\u0072\u0035\u0075\u0071\u004c\u0056\u007d\u0022\u005a\u004c\u003a\u0077\u0029\u0063\u004d\u0042\u0079\u0074\u0024\u0073\u0062\u0024\u002c\u0031\u0026\u0079\u004d\u0053\u0056\u005a\u0023\u0052\u0054\u0076\u0062\u004c\u0075\u0048\u003b\u0067\u0044\u006d\u0034\u0050\u0033\u0075\u0035\u0035\u0039\u006a\u007c\u0063\u002e\u0066\u0076\u003a\u0056\u0028\u006e\u006b\u004b\u0052\u0029\u0057\u0046\u002e\u0022\u0043\u0029\u0075\u007a\u006e\u0058\u0048\u0040\u0022\u0022\u007a\u007d\u004c\u0025\u0043\u003b\u0038\u0061\u0037\u0058\u0071\u0042\u0054\u0035\u003e\u004c\u003e\u007c\u004e\u003e\u0052\u0033\u0078\u002f\u0070\u0060\u0036\u0061\u0076\u0048\u0048\u0075\u0031\u007a\u003f\u0048\u0022\u006d\u006a\u007e\u0042\u0050\u002b\u0043\u0077\u0059\u005e\u0075\u003e\u0023\u0073\u0034\u004a\u0063\u006e\u0052\u004c\u004b\u006d\u0047\u0069\u005a\u002e\u0049\u005e\u006b\u0073\u003c\u005a\u0026\u004f\u0043\u0050\u0026\u0063\u005d\u002a\u0048\u006f\u005a\u0078\u0035\u0055\u003a\u0078\u004f\u002a\u0036\u0026\u005d\u0059\u0038\u003b\u007d\u006b\u0073\u0028\u006b\u0029\u0039\u0050\u0026\u0063\u005d\u0059\u0074\u0070\u0025\u002c\u0046\u004d\u0071\u0021\u002a\u0058\u0026\u004a\u006f\u0073\u0040\u0055\u0077\u0036\u0026\u0062\u005a\u0044\u0049\u006a\u007a\u006c\u003d\u0075\u0051\u0055\u0077\u0036\u0026\u006e\u0042\u0062\u006f\u004a\u0049\u003d\u0022\u0072\u0057\u002b\u002b\u0055\u003b\u006e\u002e\u0054\u006f\u002a\u0022\u0064\u0033\u0070\u0068\u002b\u0061\u0029\u0062\u002c\u0074\u006c\u0044\u007c\u0077\u0038\u0067\u0058\u0068\u0058\u0048\u0062\u004f\u005f\u007b\u003f\u002f\u0054\u0047\u0038\u0040\u0021\u0033\u0070\u0067\u005b\u003c\u0049\u0061\u0047\u004f\u004f\u0070\u003b\u0041\u0048\u0032\u003a\u0045\u0023\u0072\u007d\u0075\u007b\u007d\u0043\u0022\u0059\u0046\u0079\u003b\u0023\u006e\u004d\u003b\u006f\u002a\u006d\u0045\u0041\u003a\u0047\u004f\u0022\u0051\u0048\u003b\u0078\u0060\u0065\u007d\u0021\u0078\u007b\u0076\u0048\u004a\u0058\u0068\u0068\u003e\u006b\u004d\u007b\u0077\u005f\u004e\u0051\u0053\u005b\u005b\u0038\u004b\u005d\u0067\u005f\u0077\u006e\u0070\u002e\u006c\u0044\u003b\u0025\u0028\u0045\u0036\u0036\u0035\u0079\u0030\u0064\u0075\u0048\u0052\u006f\u0075\u006c\u0062\u003c\u0046\u002e\u0033\u003c\u0035\u0070\u0047\u003e\u003f\u0025\u0035\u0041\u0071\u0032\u0063\u003b\u0043\u0030\u0021\u0055\u004c\u0043\u0062\u0039\u004f\u002c\u007c\u0032\u0021\u0079\u0079\u002e\u0063\u0079\u0048\u006a\u0060\u007e\u0065\u0077\u0031\u006d\u005f\u0079\u004e\u0050\u004f\u0063\u0038\u0064\u0031\u0065\u0063\u004c\u0028\u002c\u003c\u0060\u0046\u005b\u0021\u002b\u003a\u002a\u006f\u0078\u003c\u0060\u007e\u002f\u0077\u0031\u0065\u0034\u003a\u003f\u002e\u0077\u002f\u0072\u0040\u0067\u0022\u007a\u0049\u0039\u006a\u004d\u0067\u0052\u0033\u004e\u003a\u0022\u006d\u0066\u004c\u0059\u003d\u005a\u0050\u006f\u006c\u0071\u0049\u0072\u0043\u0032\u0066\u003a\u005a\u0026\u0063\u0029\u0076\u0058\u0023\u0061\u0033\u0047\u0038\u003b\u002f\u0029\u0060\u0035\u0047\u0070\u0068\u0067\u003e\u0064\u0047\u0038\u003a\u0068\u0065\u0060\u0028\u002c\u0025\u0075\u0071\u0069\u0023\u006b\u0069\u0056\u006e\u0079\u0031\u0052\u0074\u0069\u007e\u0072\u0060\u0049\u0033\u006a\u0078\u0056\u003a\u0079\u005b\u0060\u0039\u0063\u0025\u0040\u0067\u0024\u005d\u0069\u005e\u0056\u0023\u006b\u0022\u0073\u002c\u007b\u006f\u004c\u0021\u002c\u0056\u0076\u0049\u005e\u005f\u0030\u0024\u005f\u002b\u002a\u003c\u0066\u002f\u0043\u0033\u0077\u005f\u004d\u0028\u0042\u0060\u005f\u0064\u0058\u006c\u0066\u0032\u0056\u0056\u0049\u0037\u005d\u006c\u0055\u007b\u006e\u007b\u0055\u005e\u0075\u002f\u0065\u0060\u0047\u0051\u0028\u004e\u0032\u002b\u0037\u0066\u003a\u005b\u005d\u0073\u007c\u004d\u0055\u0024\u0074\u005a\u0064\u0046\u0056\u0055\u005d\u004b\u0060\u0042\u003e\u0074\u003e\u005b\u004b\u0046\u005e\u0059\u0063\u0074\u002f\u003b\u0022\u006b\u006e\u0068\u0047\u0065\u004b\u0062\u006f\u0060\u005f\u0066\u006e\u0022\u0051\u0067\u0068\u0028\u006b\u0050\u0064\u0035\u0055\u0038\u003d\u0067\u0077\u0062\u003d\u0040\u0047\u0023\u0045\u0028\u0035\u0026\u0073\u0032\u0077\u0049\u0041\u0041\u005d\u0058\u0061\u0060\u0050\u007d\u007e\u0022\u0040\u0069\u004e\u006c\u0064\u0054\u0034\u006e\u0059\u0050\u007d\u0031\u0024\u0052\u0037\u0058\u006c\u0057\u0030\u0042\u0044\u0064\u0047\u0049\u007b\u0029\u003c\u004e\u0036\u0055\u004f\u007a\u0064\u003b\u0035\u007b\u004e\u0038\u004e\u0030\u007d\u007e\u003b\u004a\u0022\u0035\u0043\u003a\u0051\u002a\u0040\u0045\u005d\u0075\u0072\u006d\u004a\u002b\u003f\u0079\u002a\u0033\u0079\u0055\u0062\u002a\u0045\u0066\u0049\u0076\u0023\u006d\u004a\u004c\u003f\u0079\u002a\u0033\u0079\u0046\u0066\u006f\u005a\u005e\u0043\u0040\u0052\u0049\u0063\u002a\u002b\u002f\u0033\u005a\u004d\u0055\u0051\u007a\u006e\u0038\u0032\u0041\u0055\u0079\u0036\u003b\u007b\u0022\u0056\u0037\u0034\u006f\u007a\u007c\u004c\u0041\u0046\u005f\u0048\u003a\u004a\u002c\u006a\u002c\u0060\u0033\u0079\u0065\u002e\u002b\u0059\u0073\u0033\u004c\u0043\u0033\u006d\u0076\u0041\u0021\u007a\u004e\u0053\u0076\u0041\u0055\u0042\u0059\u0053\u006c\u0021\u005e\u0031\u0042\u0026\u0072\u003c\u0050\u0058\u007b\u003f\u002a\u002a\u0036\u0077\u006a\u007a\u003f\u0056\u0067\u007e\u0032\u003f\u0025\u0030\u0073\u0029\u0046\u0037\u0033\u0051\u003d\u0063\u0054\u0029\u0040\u0050\u0058\u0073\u0066\u0060\u0033\u0079\u0058\u0073\u0066\u0060\u0026\u0046\u0066\u0035\u0067\u0032\u007e\u0031\u0023\u004a\u006a\u0034\u004e\u006c\u0030\u0071\u0069\u005e\u0046\u0035\u0033\u0058\u0067\u0029\u0021\u007a\u0049\u0074\u0068\u0063\u003e\u007d\u0030\u0037\u002e\u0073\u0030\u004d\u0050\u003c\u003f\u0039\u007c\u004c\u0060\u0029\u0036\u007e\u0050\u0021\u004d\u002b\u0059\u005e\u0050\u003c\u0062\u004a\u007c\u004c\u0060\u0029\u0021\u007a\u0072\u0034\u0075\u0065\u0036\u0071\u0065\u0067\u0076\u006c\u007e\u0071\u006a\u0070\u007a\u0035\u0033\u006d\u0076\u0041\u0021\u007a\u004e\u0053\u0076\u0041\u0021\u007a\u004e\u0053\u0076\u0041\u0030\u0031\u0047\u0034\u0033\u006d\u0056\u0075\u0057\u002f\u0024\u0050\u0021\u005a\u0039\u0059\u0072\u004e\u0021\u0053\u0029\u002b\u0066\u003a\u0065\u0046\u0074\u004c\u0053\u0057\u006a\u0044\u0021\u0043\u0033\u0074\u0066\u004c\u0073\u006d\u003c\u007e\u0071\u005a\u0047\u0065\u004f\u005d\u0040\u0052\u0042\u0076\u003c\u0072\u006c\u0022\u0028\u004d\u002b\u002b\u002b\u006f\u0057\u003f\u0021\u007a\u004e\u0053\u0076\u0041\u0021\u007a\u004e\u0053\u0053\u0078\u007c\u005e\u0077\u0033\u0067\u0028\u0040\u0045\u0035\u0069\u0030\u0031\u0047\u0034\u0048\u0030\u0070\u0075\u006a\u0046\u0025\u0068\u0072\u0059\u007b\u003f\u004a\u0043\u0033\u0074\u0073\u006c\u006d\u0038\u003f\u007e\u0028\u0024\u003d\u0025\u0046\u004c\u0032\u0072\u0049\u0034\u0068\u0065\u003d\u004c\u0052\u003b\u0062\u0062\u0058\u004b\u0052\u0032\u0040\u0052\u0074\u003e\u004e\u0072\u0070\u0075\u004e\u0046\u002c\u004a\u004a\u0057\u007e\u0049\u0034\u0055\u003a\u004a\u0048\u003d\u005d\u0043\u003b\u0046\u004d\u0066\u005d\u0057\u007c\u0022\u005f\u0046\u0033\u006d\u0076\u0041\u0021\u007a\u004e\u0053\u0076\u0041\u0055\u0042\u0022\u0036\u0051\u0037\u0029\u0071\u0038\u0046\u0052\u002f\u0043\u007a\u0057\u003f\u0021\u007a\u004e\u0053\u0076\u0041\u0055\u0042\u0059\u0053\u006c\u0021\u0066\u0060\u0051\u002e\u004b\u0062\u006f\u005a\u0048\u0046\u0056\u0064\u004e\u0034\u003d\u0032\u0038\u0052\u0031\u005e\u002b\u002b\u002b\u006f\u0057\u003f\u0021\u007a\u004e\u0053\u0076\u0041\u0030\u0031\u006f\u0021\u006b\u002b\u003d\u004c\u002c\u0079\u002c\u003c\u0043\u0025\u0058\u004f\u0043\u0046\u0072\u0034\u0035\u0021\u0053\u0025\u0042\u002e\u0033\u0068\u0041\u0065\u0063\u0069\u0051\u0073\u0047\u006f\u0057\u003f\u0021\u007a\u004e\u0053\u0076\u0041\u0021\u007a\u004e\u0053\u002a\u0057\u0048\u003a\u004d\u007e\u0051\u0060\u0023\u0030\u0041\u0042\u0036\u0048\u0041\u006b\u0022\u0053\u003a\u004d\u0050\u003c\u006a\u004a\u0047\u006f\u006e\u007e\u0040\u0052\u006d\u005a\u0063\u0041\u006c\u004b\u003e\u0034\u002c\u0030\u0048\u0038\u0042\u002e\u0057\u004c\u004c\u005a\u0021\u0068\u002e\u004a\u0068\u0036\u0063\u0041\u003f\u002a\u0036\u0077\u0067\u004a\u0042\u0046\u0062\u003b\u0031\u0068\u0053\u0032\u0030\u0029\u002a\u007a\u0068\u0036\u0030\u006c\u0056\u0061\u0074\u0056\u0056\u0068\u0072\u0059\u0038\u006e\u0057\u0036\u0068\u0076\u0055\u002b\u0036\u004d\u0050\u003c\u0066\u0078\u0078\u0071\u004e\u006e\u0074\u0052\u003c\u0053\u0076\u0041\u0021\u007a\u004e\u0053\u0076\u0041\u0021\u002f\u003d\u0034\u0048\u0076\u004f\u0038\u006b\u007e\u002b\u002b\u002b\u006f\u0057\u003f\u0021\u007a\u004e\u0053\u0076\u0041\u0030\u0031\u006f\u0021\u006b\u002b\u003d\u004c\u002c\u0079\u002c\u003c\u0043\u0025\u0062\u005d\u006b\u007d\u0069\u0051\u0068\u004c\u0059\u005e\u0033\u0031\u0066\u006b\u006f\u006c\u0021\u0030\u0021\u007a\u004e\u0053\u0076\u0041\u0021\u007a\u004e\u0053\u0076\u0041\u0021\u007a\u0028\u0074\u0057\u0064\u0060\u007b\u0076\u003b\u005e\u005a\u0038\u0045\u0064\u007b\u0072\u0048\u0021\u0053\u0049\u002e\u0021\u004b\u0075\u004d\u002e\u0073\u006a\u005e\u0074\u0067\u0073\u004a\u007a\u006c\u0048\u0046\u0053\u004b\u007d\u003c\u0073\u0045\u0031\u005e\u0075\u002f\u0058\u0068\u0055\u0058\u0030\u0029\u002e\u003c\u004e\u0053\u007e\u0076\u006a\u0075\u002b\u0031\u0078\u0057\u004c\u005a\u0058\u006e\u0037\u0023\u006d\u004a\u0063\u003f\u0074\u007d\u007d\u003c\u005b\u0076\u006c\u0058\u0032\u006e\u0023\u0072\u003a\u0077\u007d\u007d\u0079\u005e\u0078\u002f\u005d\u0066\u007a\u006c\u005f